350	// Claim 由调用方传入当前时间，为活动中的设备领取当前可执行的操作。
351	//
352	// 派发新的下载或安装操作要求设备在线、当前时间位于维护窗口 [start, end) 内、
353	// 所在批次已被前一批全部成功放行。首次领取下载前会再次核对设备当前版本，
354	// 不兼容则将该设备（带阶段、原因和时间）记为失败，返回 ErrIncompatibleVersion；
355	// 开启回滚的活动还会在首次领取下载时把设备当时的当前版本锁定为回滚目标，
356	// 后续普通上报不改变它。
357	// 开启回滚且安装失败已被接受后，设备领取回滚操作：首次领取同样要求设备在线
358	// 且时间位于原维护窗口 [start, end) 内（不受批次放行影响），返回的操作带锁定
359	// 目标版本；离线或窗口外保留待办。回滚已领取但未完成时再次查询返回同一标识，
360	// 且可在窗口外、截止前提交结果。
361	// 已领取但未完成的操作（下载/安装/回滚）再次查询时返回同一标识，不要求在线或位于窗口内。
362	// 离线设备保留待办；离线或窗口外暂无可领取的新操作时返回 (nil, nil)。
363	// 时间缺失或相对本活动已接受的时间倒退时拒绝，且不改变状态。
364	func (s *Store) Claim(campaignID, deviceID string, at time.Time) (*Operation, error) {
365		s.mu.Lock()
366		defer s.mu.Unlock()
367		if err := s.checkOpen(); err != nil {
368			return nil, err
369		}
370		c, cd, err := s.lookupCampaignDevice(campaignID, deviceID)
371		if err != nil {
372			return nil, err
373		}
374		if at.IsZero() {
375			return nil, ErrInvalidTime
376		}
377		if at.Before(c.LastTime) {
378			return nil, fmt.Errorf("%w: %v before %v", ErrTimeRegression, at, c.LastTime)
379		}
380		var op *Operation
381		var reject error
382		err = s.commit(func() error {
383			// 到达截止时间：未结束设备全部超时并落盘，本次领取拒绝。
384			// 即使查询的设备已有终态，其他未结束设备仍要级联超时。
385			if !at.Before(c.Deadline) {
386				c.LastTime = at
387				s.applyTimeout(c, at)
388				reject = ErrCampaignEnded
389				return nil
390			}
391			if c.Ended {
392				// 纯拒绝路径：不推进时间基线，不改状态。
393				reject = ErrCampaignEnded
394				return nil
395			}
396			if isTerminal(cd.Status) {
397				reject = fmt.Errorf("%w: %s", ErrDeviceFinished, deviceID)
398				return nil
399			}
400			c.LastTime = at
401			// 已领取但未完成的操作：查询仍返回原标识，不要求在线或位于窗口内。
402			if out := outstandingOp(c, cd); out != nil {
403				op = out
404				return nil
405			}
406			// 安装失败已接受、等待回滚：回滚是该设备的善后操作，不受批次放行影响。
407			// 首次领取要求在线且位于原维护窗口 [start,end) 内；离线或窗口外保留待办。
408			if cd.Status == DeviceAwaitingRollback {
409				if !s.devices[deviceID].Online {
410					return nil
411				}
412				if at.Before(c.WindowStart) || !at.Before(c.WindowEnd) {
413					return nil
414				}
415				cd.Rollback.Claimed = true
416				cd.Rollback.ClaimedAt = at
417				cd.Status = DeviceRollingBack
418				cd.Phase = StageRollback
419				cd.At = at
420				op = &Operation{
421					ID:            cd.Rollback.ID,
422					CampaignID:    c.ID,
423					DeviceID:      deviceID,
424					Kind:          StageRollback,
425					TargetVersion: cd.RollbackTarget,
426				}
427				return nil
428			}
429			// 尚未领取的新阶段：先看批次是否放行（不放行时无操作可领）。
430			if !s.batchOpen(c, cd) {
431				return nil
432			}
433			if !s.devices[deviceID].Online {
434				return nil // 离线保留待办，上线后继续
435			}
436			if at.Before(c.WindowStart) || !at.Before(c.WindowEnd) {
437				return nil // 窗口外不派发新操作；窗口为 [start, end)
438			}
439			if !cd.Download.Claimed {
440				// 首次领取下载前再次检查当前版本。
441				current := s.devices[deviceID].Version
442				if !containsString(s.versions[c.Target].AllowedFrom, current) {
443					reason := fmt.Sprintf("version %s is not compatible with target %s", current, c.Target)
444					// 该设备在下载阶段失败：领取即触发，记录阶段、原因和时间。
445					cd.Download.Claimed = true
446					cd.Download.ClaimedAt = at
447					cd.Download.HasResult = true
448					cd.Download.Success = false
449					cd.Download.Reason = reason
450					cd.Download.At = at
451					s.failDevice(c, cd, StageDownload, reason, at)
452					reject = fmt.Errorf("%w: device %s version %s", ErrIncompatibleVersion, deviceID, current)
453					return nil
454				}
455				// 开启回滚时，把首次领取下载时设备的当前版本锁定为回滚目标；
456				// 此后普通上报不改变它，也不要求该版本另行登记为升级目标。
457				if c.RollbackOnFailure && cd.RollbackTarget == "" {
458					cd.RollbackTarget = current
459				}
460				cd.Download.Claimed = true
461				cd.Download.ClaimedAt = at
462				cd.Status = DeviceDownloading
463				cd.At = at
464				op = &Operation{ID: cd.Download.ID, CampaignID: c.ID, DeviceID: deviceID, Kind: StageDownload}
465				return nil
466			}
467			// 下载已成功：领取安装（尚未领取的安装仍须在线且位于窗口内）。
468			cd.Install.Claimed = true
469			cd.Install.ClaimedAt = at
470			cd.Status = DeviceInstalling
471			cd.At = at
472			op = &Operation{ID: cd.Install.ID, CampaignID: c.ID, DeviceID: deviceID, Kind: StageInstall}
473			return nil
474		})
475		if err != nil {
476			return nil, err
477		}
478		if reject != nil {
479			return nil, reject
480		}
481		return op, nil
482	}
483	
484	// outstandingOp 返回设备已领取但尚无结果的操作；没有则返回 nil。
485	func outstandingOp(c *campaignState, cd *campaignDevice) *Operation {
486		switch {
487		case cd.Download.Claimed && !cd.Download.HasResult:
488			return &Operation{ID: cd.Download.ID, CampaignID: c.ID, DeviceID: cd.DeviceID, Kind: StageDownload}
489		case cd.Install.Claimed && !cd.Install.HasResult:
490			return &Operation{ID: cd.Install.ID, CampaignID: c.ID, DeviceID: cd.DeviceID, Kind: StageInstall}
491		case cd.Rollback.Claimed && !cd.Rollback.HasResult:
492			// 已领取但未完成的回滚再次领取仍返回同一标识，并继续告知恢复目标版本。
493			return &Operation{
494				ID:            cd.Rollback.ID,
495				CampaignID:    c.ID,
496				DeviceID:      cd.DeviceID,
497				Kind:          StageRollback,
498				TargetVersion: cd.RollbackTarget,
499			}
500		default:
501			return nil
502		}
503	}
504	
505	// batchOpen 判断设备所在批次是否已放行：前序所有设备必须全部成功。
506	func (s *Store) batchOpen(c *campaignState, cd *campaignDevice) bool {
507		for _, other := range c.Devices {
508			if other.Batch < cd.Batch && other.Status != DeviceSucceeded {
509				return false
510			}
511		}
512		return true
513	}
514	
515	// SubmitResult 接收设备提交的操作结果。
516	//
517	// 相同操作的相同结果重复提交返回成功，但不增加历史、不重复放行批次；
518	// 改用不同结果、跳过未领取阶段、提交未领取的回滚、提交其他设备的操作、
519	// 活动结束后的新结果均报错且不改变状态；已接受结果的重复提交在活动结束后仍有效。
520	// 下载完成后才能领取并安装；设备失败记录阶段、原因和时间，同批其他设备
521	// 继续完成，后续批次记为未执行。安装成功须附带版本等于目标版本的合规上报，
522	// 回滚成功须附带版本等于锁定回滚目标的合规上报，影子与活动在同一次持久化中更新。
523	// 开启回滚的活动中，安装失败不直接结束设备，而是保留原失败原因与时间、
524	// 令设备等待回滚；回滚失败必须给出原因，设备以回滚失败结束且影子不变。
525	// 已领取且尚未接受结果的操作在截止时刻及以后提交时，结果已经迟到：
526	// 不校验附带上报与失败原因、不接收为操作结果，直接按截止处理——未结束设备
527	// 全部超时（等待或正在回滚的记回滚超时），活动以失败结束，返回 ErrCampaignEnded。
528	// 普通设备上报不经过本方法，也不会推进活动。
529	func (s *Store) SubmitResult(res OperationResult) error {
530		s.mu.Lock()
531		defer s.mu.Unlock()
532		if err := s.checkOpen(); err != nil {
533			return err
534		}
535		c, cd, err := s.lookupCampaignDevice(res.CampaignID, res.DeviceID)
536		if err != nil {
537			return err
538		}
539		if res.At.IsZero() {
540			return ErrInvalidTime
541		}
542		// 定位操作标识所属阶段；不属于本设备的操作一律视为未知。
543		var stage string
544		var op *opState
545		switch res.OperationID {
546		case cd.Download.ID:
547			stage, op = StageDownload, &cd.Download
548		case cd.Install.ID:
549			stage, op = StageInstall, &cd.Install
550		case cd.Rollback.ID:
551			stage, op = StageRollback, &cd.Rollback
552		default:
553			return fmt.Errorf("%w: %s", ErrOperationNotFound, res.OperationID)
554		}
555		// 已接受结果：相同结果幂等（活动结束后仍有效，不增加历史、不重复放行），
556		// 不推进时间基线；不同结果冲突。均不改变状态。
557		if op.HasResult {
558			if resultMatches(op, res) {
559				return nil
560			}
561			return fmt.Errorf("%w: operation %s", ErrResultConflict, res.OperationID)
562		}
563		if res.At.Before(c.LastTime) {
564			return fmt.Errorf("%w: %v before %v", ErrTimeRegression, res.At, c.LastTime)
565		}
566		if !op.Claimed {
567			// 标识是本设备未来阶段的操作但尚未领取：属于跳过阶段（含未领取的回滚）。
568			return fmt.Errorf("%w: %s", ErrOperationNotClaimed, res.OperationID)
569		}
570		// 已领取且尚未接受结果的操作在截止时刻及以后提交：结果已经迟到，
571		// 不再接收为操作结果，也不校验附带上报或失败原因——直接按截止处理：
572		// 未结束设备全部超时（等待/正在回滚的记回滚超时），活动以失败结束，
573		// 状态时间与活动结束时间采用本次提交时间，返回 ErrCampaignEnded。
574		// 活动可能已被显式推进到截止而结束：applyTimeout 对已结束活动是空操作，
575		// 结果仍按截止拒绝，不能因附带配置非法或缺少原因改成相应的校验错误。
576		if !res.At.Before(c.Deadline) {
577			if err := s.commit(func() error {
578				c.LastTime = res.At
579				s.applyTimeout(c, res.At)
580				return nil
581			}); err != nil {
582				return err
583			}
584			return ErrCampaignEnded
585		}
586		if !res.Success && res.Reason == "" {
587			return ErrInvalidReason
588		}
589		if res.Success && (stage == StageInstall || stage == StageRollback) {
590			// 安装上报版本必须等于升级目标；回滚上报版本必须等于锁定的回滚目标。
591			wantVersion := c.Target
592			if stage == StageRollback {
593				wantVersion = cd.RollbackTarget
594			}
595			if err := s.validateSuccessReport(res, wantVersion); err != nil {
596				return err
597			}
598		}
599		var reject error
600		err = s.commit(func() error {
601			// 活动已结束且提交时间越过截止时间：只推进时间基线并拒绝
602			// （未结束活动的截止处理已在提交前完成，不会到达这里）。
603			if !res.At.Before(c.Deadline) {
604				c.LastTime = res.At
605				s.applyTimeout(c, res.At)
606				reject = ErrCampaignEnded
607				return nil
608			}
609			if c.Ended {
610				// 活动结束后的新结果：拒绝且不改状态（重复结果已在提交前处理）。
611				reject = ErrCampaignEnded
612				return nil
613			}
614			if isTerminal(cd.Status) {
615				reject = fmt.Errorf("%w: %s", ErrDeviceFinished, res.DeviceID)
616				return nil
617			}
618			c.LastTime = res.At
619			op.HasResult = true
620			op.Success = res.Success
621			op.Reason = res.Reason
622			op.At = res.At
623			if !res.Success {
624				switch {
625				case stage == StageInstall && c.RollbackOnFailure:
626					// 安装失败：保留原因和时间，设备转入等待回滚（非终态）；
627					// 同批其他设备继续，后续批次立即记为未执行，活动暂不结束。
628					s.enterRollback(c, cd, res.Reason, res.At)
629				case stage == StageRollback:
630					// 回滚失败必须给出原因：设备以回滚失败结束且影子不变。
631					s.finishRollbackFailure(c, cd, res.Reason, res.At)
632				default:
633					s.failDevice(c, cd, stage, res.Reason, res.At)
634				}
635				return nil
636			}
637			switch stage {
638			case StageDownload:
639				cd.Status = DeviceReady
640				cd.Phase = StageInstall
641				cd.Reason = ""
642				cd.At = res.At
643			case StageInstall:
644				// 安装成功：附带上报与活动同时更新、一起持久化。
645				s.applySuccessReport(cd.DeviceID, res, res.At)
646				op.ResultSeq = res.Seq
647				op.ResultVersion = res.Version
648				op.ResultConfig = cloneRaw(res.Config)
649				cd.Status = DeviceSucceeded
650				cd.Phase = StageInstall
651				cd.Reason = ""
652				cd.At = res.At
653			case StageRollback:
654				// 回滚成功：按上报规则更新影子（版本回到锁定目标），同时推进回滚状态。
655				// 期望配置、修订号与审计保持不变。
656				s.applySuccessReport(cd.DeviceID, res, res.At)
657				op.ResultSeq = res.Seq
658				op.ResultVersion = res.Version
659				op.ResultConfig = cloneRaw(res.Config)
660				cd.Status = DeviceRollbackSucceeded
661				cd.Phase = StageRollback
662				cd.Reason = ""
663				cd.At = res.At
664			}
665			c.Results = append(c.Results, ResultRecord{
666				DeviceID:    cd.DeviceID,
667				OperationID: op.ID,
668				Stage:       stage,
669				Success:     true,
670				Version:     op.ResultVersion,
671				At:          res.At,
672			})
673			s.settle(c, res.At)
674			return nil
675		})
676		if err != nil {
677			return err
678		}
679		return reject
680	}
681	
682	// resultMatches 判断提交是否为已接受结果的重复提交（同一操作、相同结果）。
683	// 安装成功结果还须附带相同的上报（序号、版本、配置）；发生时间不参与判定，
684	// 使活动结束后的重复提交仍然有效。
685	func resultMatches(op *opState, res OperationResult) bool {
686		if op.Success != res.Success || op.Reason != res.Reason {
687			return false
688		}
689		if op.Success && op.ResultSeq != 0 {
690			return op.ResultSeq == res.Seq &&
691				op.ResultVersion == res.Version &&
692				rawEqual(op.ResultConfig, res.Config)
693		}
694		return true
695	}
696	
697	// validateSuccessReport 按现有上报规则校验安装/回滚成功附带的设备上报，
698	// 且版本必须等于 wantVersion（安装为升级目标，回滚为锁定目标）。只校验，不改状态。
699	func (s *Store) validateSuccessReport(res OperationResult, wantVersion string) error {
700		d := s.devices[res.DeviceID]
701		if res.Seq == 0 {
702			return fmt.Errorf("%w: report sequence", ErrInvalidReport)
703		}
704		if res.Version == "" {
705			return fmt.Errorf("%w: report version", ErrInvalidReport)
706		}
707		if res.Version != wantVersion {
708			return fmt.Errorf("%w: version %s", ErrInvalidReport, res.Version)
709		}
710		if _, err := validateConfig(res.Config); err != nil {
711			return fmt.Errorf("%w: config", ErrInvalidReport)
712		}
713		switch {
714		case res.Seq < d.LastSeq:
715			return fmt.Errorf("%w: stale sequence", ErrInvalidReport)
716		case res.Seq == d.LastSeq:
717			if !(res.Version == d.Version && res.At.Equal(d.LastReportTime) && rawEqual(res.Config, d.Reported)) {
718				return fmt.Errorf("%w: sequence conflict", ErrInvalidReport)
719			}
720		}
721		return nil
722	}
723	
724	// applySuccessReport 按 Report 的既有规则写入影子（调用方已校验）。
725	// 只更新上报侧（版本、上报配置、序号、在线状态与配置差异），
726	// 不动期望配置、修订号与审计。
727	func (s *Store) applySuccessReport(deviceID string, res OperationResult, at time.Time) {
728		d := s.devices[deviceID]
729		if res.Seq == d.LastSeq {
730			// 相同序号的完全重复上报：影子不变，只随活动一起落盘。
731			return
732		}
733		d.Reported = cloneRaw(res.Config)
734		d.Version = res.Version
735		d.Online = true
736		d.LastSeq = res.Seq
737		d.LastReportTime = at
738		d.refreshDiff(at)
739	}
740	
741	// enterRollback 在开启回滚的活动中处理已接受的安装失败：
742	// 保留原安装失败的原因与时间，令设备等待回滚（非终态）；
743	// 同批其他设备可继续，后续批次立即记为未执行，但活动暂不结束。
744	func (s *Store) enterRollback(c *campaignState, cd *campaignDevice, reason string, at time.Time) {
745		cd.Status = DeviceAwaitingRollback
746		cd.Phase = StageRollback
747		cd.Reason = reason
748		cd.At = at
749		c.Results = append(c.Results, ResultRecord{
750			DeviceID:    cd.DeviceID,
751			OperationID: cd.Install.ID,
752			Stage:       StageInstall,
753			Success:     false,
754			Reason:      reason,
755			At:          at,
756		})
757		skipLaterBatches(c, cd, at)
758		// 不结束活动：设备进入非终态的等待回滚，活动要等其回滚结束。
759	}
760	
761	// finishRollbackFailure 处理已接受的回滚失败：必须给出原因，
762	// 设备以回滚失败结束，影子不变（失败结果不附带、不应用上报）。
763	func (s *Store) finishRollbackFailure(c *campaignState, cd *campaignDevice, reason string, at time.Time) {
764		cd.Status = DeviceRollbackFailed
765		cd.Phase = StageRollback
766		cd.Reason = reason
767		cd.At = at
768		c.Results = append(c.Results, ResultRecord{
769			DeviceID:    cd.DeviceID,
770			OperationID: cd.Rollback.ID,
771			Stage:       StageRollback,
772			Success:     false,
773			Reason:      reason,
774			At:          at,
775		})
776		s.settle(c, at)
777	}
778	
779	// skipLaterBatches 把后续批次中尚未结束的设备立即记为未执行。
780	func skipLaterBatches(c *campaignState, cd *campaignDevice, at time.Time) {
781		for _, other := range c.Devices {
782			if other.Batch > cd.Batch && !isTerminal(other.Status) {
783				other.Status = DeviceSkipped
784				other.Phase = pendingPhase(other)
785				other.Reason = "not executed: previous batch failed"
786				other.At = at
787			}
788		}
789	}
790	
791	// failDevice 将设备记为失败，记录阶段、原因和时间；后续批次全部记为未执行，
792	// 本批其他设备继续。若全部设备已到终态，则活动以失败结束。
793	func (s *Store) failDevice(c *campaignState, cd *campaignDevice, phase, reason string, at time.Time) {
794		cd.Status = DeviceFailed
795		cd.Phase = phase
796		cd.Reason = reason
797		cd.At = at
798		c.Results = append(c.Results, ResultRecord{
799			DeviceID:    cd.DeviceID,
800			OperationID: opIDFor(cd, phase),
801			Stage:       phase,
802			Success:     false,
803			Reason:      reason,
804			At:          at,
805		})
806		skipLaterBatches(c, cd, at)
807		s.settle(c, at)
808	}
809	
810	func opIDFor(cd *campaignDevice, phase string) string {
811		switch phase {
812		case StageInstall:
813			return cd.Install.ID
814		case StageRollback:
815			return cd.Rollback.ID
816		default:
817			return cd.Download.ID
818		}
819	}
820	
821	// pendingPhase 返回设备尚未完成的阶段：下载成功后停留在安装阶段。
822	func pendingPhase(cd *campaignDevice) string {
823		if cd.Download.HasResult && cd.Download.Success {
824			return StageInstall
825		}
826		return StageDownload
827	}
828	
829	// applyTimeout 在当前时间达到截止时间时，把所有未结束设备记为超时，
830	// 已有终态保持不变，活动记为失败并结束。等待回滚或正在回滚的设备
831	// 以回滚阶段超时结束；不改写或清空影子。
832	func (s *Store) applyTimeout(c *campaignState, at time.Time) {
833		if c.Ended {
834			return
835		}
836		for _, cd := range c.Devices {
837			if isTerminal(cd.Status) {
838				continue
839			}
840			switch cd.Status {
841			case DeviceAwaitingRollback, DeviceRollingBack:
842				cd.Status = DeviceRollbackTimeout
843				cd.Phase = StageRollback
844			default:
845				cd.Status = DeviceTimeout
846				cd.Phase = pendingPhase(cd)
847			}
848			cd.Reason = "deadline exceeded"
849			cd.At = at
850		}
851		c.Status = CampaignFailed
852		c.Ended = true
853		c.EndedAt = at
854	}
855	
856	// settle 在全部设备到达终态时结束活动：全部成功则成功，否则失败。
857	// 即使回滚成功，设备也不是 succeeded，活动仍为失败。
858	func (s *Store) settle(c *campaignState, at time.Time) {
859		allSucceeded := true
860		for _, cd := range c.Devices {
861			if !isTerminal(cd.Status) {
862				return
863			}
864			if cd.Status != DeviceSucceeded {
865				allSucceeded = false
866			}
867		}
868		c.Ended = true
869		c.EndedAt = at
870		if allSucceeded {
871			c.Status = CampaignSucceeded
872		} else {
873			c.Status = CampaignFailed
874		}
875	}
876	
877	func isTerminal(status string) bool {
878		switch status {
879		case DeviceSucceeded, DeviceFailed, DeviceTimeout, DeviceSkipped,
880			DeviceRollbackSucceeded, DeviceRollbackFailed, DeviceRollbackTimeout:
881			return true
882		default:
883			return false
884		}
885	}
886	
887	// AdvanceCampaign 用调用方给出的当前时间推进活动：到达截止时间时把未结束
888	// 设备全部记为超时并结束活动。时间缺失或相对已接受时间倒退时拒绝且不改状态。
889	// 未到截止时间或活动已结束时为空操作。
890	func (s *Store) AdvanceCampaign(campaignID string, at time.Time) error {
891		s.mu.Lock()
892		defer s.mu.Unlock()
893		if err := s.checkOpen(); err != nil {
894			return err
895		}
896		c, err := s.lookupCampaign(campaignID)
897		if err != nil {
898			return err
899		}
900		if at.IsZero() {
901			return ErrInvalidTime
902		}
903		if at.Before(c.LastTime) {
904			return fmt.Errorf("%w: %v before %v", ErrTimeRegression, at, c.LastTime)
905		}
906		if c.Ended {
907			return nil
908		}
909		if at.Before(c.Deadline) {
910			// 仅推进时间基线也持久化，使重开后的倒退判断仍然有效。
911			return s.commit(func() error { c.LastTime = at; return nil })
912		}
913		return s.commit(func() error {
914			c.LastTime = at
915			s.applyTimeout(c, at)
916			return nil
917		})
918	}
919	
920	func (s *Store) lookupCampaign(campaignID string) (*campaignState, error) {
921		if campaignID == "" {
922			return nil, ErrInvalidCampaignID
923		}
924		c, ok := s.campaigns[campaignID]
925		if !ok {
926			return nil, fmt.Errorf("%w: %s", ErrCampaignNotFound, campaignID)
927		}
928		return c, nil
929	}
930	
931	func (s *Store) lookupCampaignDevice(campaignID, deviceID string) (*campaignState, *campaignDevice, error) {
932		c, err := s.lookupCampaign(campaignID)
933		if err != nil {
934			return nil, nil, err
935		}
936		if deviceID == "" {
937			return nil, nil, ErrInvalidDeviceID
938		}
939		i, ok := c.index[deviceID]
940		if !ok {
941			return nil, nil, fmt.Errorf("%w: %s", ErrDeviceNotInCampaign, deviceID)
942		}
943		return c, c.Devices[i], nil
944	}
