1008	// GetCampaign 查询活动：创建者、目标版本、每批设备状态、
1009	// 失败或超时原因及结果历史。返回数据为独立副本。
1010	func (s *Store) GetCampaign(campaignID string) (CampaignView, error) {
1011		s.mu.Lock()
1012		defer s.mu.Unlock()
1013		if err := s.checkOpen(); err != nil {
1014			return CampaignView{}, err
1015		}
1016		c, err := s.lookupCampaign(campaignID)
1017		if err != nil {
1018			return CampaignView{}, err
1019		}
1020		v := CampaignView{
1021			ID:                c.ID,
1022			Operator:          c.Operator,
1023			TargetVersion:     c.Target,
1024			CreatedAt:         c.CreatedAt,
1025			BatchSize:         c.BatchSize,
1026			WindowStart:       c.WindowStart,
1027			WindowEnd:         c.WindowEnd,
1028			Deadline:          c.Deadline,
1029			RollbackOnFailure: c.RollbackOnFailure,
1030			Status:            c.Status,
1031			Ended:             c.Ended,
1032			EndedAt:           c.EndedAt,
1033			Results:           make([]ResultRecord, len(c.Results)),
1034		}
1035		copy(v.Results, c.Results)
1036		for _, cd := range c.Devices {
1037			dv := DeviceStatusView{
1038				DeviceID:       cd.DeviceID,
1039				Batch:          cd.Batch,
1040				Status:         cd.Status,
1041				Phase:          cd.Phase,
1042				Reason:         cd.Reason,
1043				At:             cd.At,
1044				DownloadID:     cd.Download.ID,
1045				InstallID:      cd.Install.ID,
1046				RollbackID:     cd.Rollback.ID,
1047				RollbackTarget: cd.RollbackTarget,
1048			}
1049			// 安装失败原因与时间独立保留，进入回滚后也不被回滚结果覆盖。
1050			if cd.Install.HasResult && !cd.Install.Success {
1051				dv.InstallFailReason = cd.Install.Reason
1052				dv.InstallFailAt = cd.Install.At
1053			}
1054			// 回滚结果的原因与时间单独呈现。
1055			if cd.Rollback.HasResult {
1056				dv.RollbackResult = true
1057				dv.RollbackSuccess = cd.Rollback.Success
1058				dv.RollbackReason = cd.Rollback.Reason
1059				dv.RollbackAt = cd.Rollback.At
1060			}
1061			v.Devices = append(v.Devices, dv)
1062			for len(v.Batches) <= cd.Batch {
1063				v.Batches = append(v.Batches, BatchView{Index: len(v.Batches)})
1064			}
1065			v.Batches[cd.Batch].Devices = append(v.Batches[cd.Batch].Devices, dv)
1066		}
1067		return v, nil
1068	}
1069	
1070	// DeviceWork 是设备当前版本与待执行操作的查询结果。
1071	type DeviceWork struct {
1072		DeviceID string
1073		Version  string
1074		Online   bool
1075		// CampaignID 是设备当前所在的未结束活动；没有时为空。
1076		CampaignID string
1077		// Pending 是设备仍待完成的操作（至多一个）：已领取未完成或下一阶段可领取。
1078		// 等待回滚时为尚未领取的回滚操作，其 TargetVersion 给出锁定的回滚目标。
1079		Pending *Operation
1080		// PendingClaimed 表示 Pending 是否已领取（未领取的安装或回滚仍须等维护窗口）。
1081		PendingClaimed bool
1082	}
1083	
1084	// GetDeviceWork 查询设备当前版本及其待执行操作。
1085	func (s *Store) GetDeviceWork(deviceID string) (DeviceWork, error) {
1086		s.mu.Lock()
1087		defer s.mu.Unlock()
1088		if err := s.checkOpen(); err != nil {
1089			return DeviceWork{}, err
1090		}
1091		d, err := s.lookup(deviceID)
1092		if err != nil {
1093			return DeviceWork{}, err
1094		}
1095		w := DeviceWork{DeviceID: deviceID, Version: d.Version, Online: d.Online}
1096		for id, c := range s.campaigns {
1097			if c.Ended {
1098				continue
1099			}
1100			i, ok := c.index[deviceID]
1101			if !ok {
1102				continue
1103			}
1104			cd := c.Devices[i]
1105			w.CampaignID = id
1106			if out := outstandingOp(c, cd); out != nil {
1107				w.Pending = out
1108				w.PendingClaimed = true
1109			} else if cd.Status == DeviceAwaitingRollback {
1110				// 回滚待领取：显示回滚目标，标记为尚未领取。
1111				w.Pending = &Operation{
1112					ID:            cd.Rollback.ID,
1113					CampaignID:    c.ID,
1114					DeviceID:      deviceID,
1115					Kind:          StageRollback,
1116					TargetVersion: cd.RollbackTarget,
1117				}
1118				w.PendingClaimed = false
1119			} else if !isTerminal(cd.Status) {
1120				kind := StageDownload
1121				id := cd.Download.ID
1122				if cd.Download.HasResult {
1123					kind, id = StageInstall, cd.Install.ID
1124				}
1125				w.Pending = &Operation{ID: id, CampaignID: c.ID, DeviceID: deviceID, Kind: kind}
1126				w.PendingClaimed = false
1127			}
1128			break
1129		}
1130		return w, nil
1131	}
1132	
1133	// ListUpgrades 返回已登记的全部升级目标版本，按目标版本字典序排列。
1134	func (s *Store) ListUpgrades() ([]VersionSpec, error) {
1135		s.mu.Lock()
1136		defer s.mu.Unlock()
1137		if err := s.checkOpen(); err != nil {
1138			return nil, err
1139		}
1140		out := make([]VersionSpec, 0, len(s.versions))
1141		for _, v := range s.versions {
1142			out = append(out, VersionSpec{Target: v.Target, AllowedFrom: append([]string(nil), v.AllowedFrom...)})
1143		}
