233				d.Audit = d.Audit[1:]
234				doc.Devices["dev-1"] = d
235			},
236			// 修订号断开：1 之后直接是 3
237			"revision gap": func(doc fixStore) {
238				d := doc.Devices["dev-1"]
239				d.Audit[1].Revision = 3
240				doc.Devices["dev-1"] = d
241			},
242			// 审计未从修订号 1 开始（条数与修订号相符，但首条修订号为 2）
243			"audit not from one": func(doc fixStore) {
244				d := doc.Devices["dev-1"]
245				d.Audit = []fixAudit{
246					{Operator: op, Time: t1, Revision: 2, Before: empty, After: a1},
247					{Operator: op, Time: t2, Revision: 3, Before: a1, After: a2},
248				}
249				doc.Devices["dev-1"] = d
250			},
251			// 首条修改前不是登记时的空对象
252			"first before not empty": func(doc fixStore) {
253				d := doc.Devices["dev-1"]
254				d.Revision = 1
255				d.Desired = a1
256				d.Audit = []fixAudit{
257					{Operator: op, Time: t1, Revision: 1, Before: x1, After: a1},
258				}
259				doc.Devices["dev-1"] = d
260			},
261			// 相邻记录断开：第二条修改前不等于第一条修改后
262			"chain broken": func(doc fixStore) {
263				d := doc.Devices["dev-1"]
264				d.Audit[1].Before = a9
265				doc.Devices["dev-1"] = d
266			},
267			// 末条修改后与当前期望配置不同
268			"last after mismatches desired": func(doc fixStore) {
269				d := doc.Devices["dev-1"]
270				d.Desired = a3
271				doc.Devices["dev-1"] = d
272			},
273			// 当前修订号大于审计条数：历史解释不了现状
274			"revision beyond audit": func(doc fixStore) {
275				d := doc.Devices["dev-1"]
276				d.Revision = 3
277				doc.Devices["dev-1"] = d
278			},
279			// 有审计却声称修订号 0
280			"audit with revision zero": func(doc fixStore) {
281				d := doc.Devices["dev-1"]
282				d.Revision = 0
283				d.Desired = empty
284				doc.Devices["dev-1"] = d
285			},
286			// 修订号 0、无审计，但期望配置不是空对象
287			"desired not empty at revision zero": func(doc fixStore) {
288				d := doc.Devices["dev-1"]
289				d.Revision = 0
290				d.Desired = a1
291				d.Audit = nil
292				doc.Devices["dev-1"] = d
293			},
294		}
295		for name, mutate := range cases {
296			t.Run(name, func(t *testing.T) {
297				doc := twoAuditDoc()
298				mutate(doc)
299				dir, original := writeFixStore(t, doc)
300				s, err := Open(dir)
301				if err == nil {
302					s.Close()
303					t.Fatalf("expected ErrCorruptStorage")
304				}
305				if !errors.Is(err, ErrCorruptStorage) {
306					t.Fatalf("error must wrap ErrCorruptStorage: %v", err)
307				}
308				// 原文件内容保持不变
309				data, rerr := os.ReadFile(filepath.Join(dir, storeFileName))
310				if rerr != nil {
311					t.Fatal(rerr)
312				}
313				if string(data) != string(original) {
314					t.Fatalf("corrupt file modified on rejected open")
315				}
316			})
317		}
318	}
319	
320	// 一台设备损坏即拒绝打开整个存储，其他正常设备也不可用。
321	func TestRestoreOneDeviceCorruptRejectsAll(t *testing.T) {
322		doc := twoAuditDoc()
323		doc.Devices["good"] = fixState{
324			Version:  "1.0",
325			Desired:  json.RawMessage(`{}`),
326			Reported: json.RawMessage(`{}`),
327		}
328		bad := doc.Devices["dev-1"]
329		bad.Audit = []fixAudit{
330			{Operator: "op", Time: "2026-10-02T12:00:00Z", Revision: 1, Before: json.RawMessage(`{}`), After: json.RawMessage(`{"a":2}`)},
331		}
332		doc.Devices["bad"] = bad
333		delete(doc.Devices, "dev-1")
334		dir, _ := writeFixStore(t, doc)
335		if _, err := Open(dir); !errors.Is(err, ErrCorruptStorage) {
336			t.Fatalf("whole store must be refused when one device history mismatches: %v", err)
337		}
338	}
